// E9-117 — emscripten's glue, typed only as far as `wasm53.ts` needs it.
//
// The module itself is generated by `tools/lua53/build.sh` and is not in the
// repository; this declaration is, so a checkout typechecks before anything
// has been built, and so the one `any` in the port is written down rather
// than implied.
declare module "*/lua53/lua53.mjs" {
  const factory: (options?: Record<string, unknown>) => Promise<Record<string, unknown>>;
  export default factory;
}
